class Solution {
  private static long gcd(long a, long b) {
    while (b != 0) {
      long t = a % b;
      a = b;
      b = t;
    }
    return a;
  }

  public long numGoodSubarrays(int[] nums, int k) {
    int n = nums.length;
    java.util.HashMap<Long, Integer> count = new java.util.HashMap<>();
    long prefix = 0, total = 0;
    count.put(0L, 1);
    for (int x : nums) {
      prefix = (prefix + x) % k;
      int c = count.getOrDefault(prefix, 0);
      total += c;
      count.put(prefix, c + 1);
    }
    for (int i = 0; i < n; ) {
      int j = i;
      while (j < n && nums[j] == nums[i]) j++;
      long len = j - i;
      long m = k / gcd(k, nums[i]);
      long c = len / m;
      long within = c * (len + 1) - m * c * (c + 1) / 2;
      total += c - within;
      i = j;
    }
    return total;
  }
}
